const NAV=[['home','หน้าหลัก'],['attendance','เช็กชื่อ'],['scores','ให้คะแนน'],['tasks','งาน/ชิ้นงาน'],['students','นักเรียน'],['rooms','ห้องเรียน'],['schedule','ตารางสอน'],['lessons','บันทึกการสอน'],['reports','รายงาน'],['settings','ตั้งค่า']];
let env,db,ui={page:'home',term:'',room:'',subject:'พลศึกษา',date:C.day(),period:1},cloud={},queue=Promise.resolve(),savePending=0,syncTimer,busy=false,cloudConflict=null,toastTimer,syncError='';
const channel=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('checkeng-records'):null;
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function localGet(k,fallback){try{return JSON.parse(localStorage.getItem(k))||fallback;}catch{return fallback;}}
