function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('checkeng-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('records');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);req.onblocked=()=>reject(Error('ปิดแท็บแอปอื่นแล้วเปิดใหม่'));});}
function readDB(key='main'){return new Promise((resolve,reject)=>{const req=db.transaction('records').objectStore('records').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function writeDB(value,key='main'){return new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').put(clone(value),key);tx.oncomplete=()=>{if(key==='main')channel?.postMessage('saved');resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('บันทึกไม่สำเร็จ'));});}
function enqueue(op){savePending++;const run=async()=>{const latest=await readDB();if(latest)env=latest;return op();};const p=queue.then(()=>navigator.locks?navigator.locks.request('checkeng-write',run):run());queue=p.catch(()=>{}).finally(()=>{savePending--;});return p;}
if(channel)channel.onmessage=async()=>{if(!db||!env)return;await queue;const latest=await readDB();if(latest){env=latest;render();}};
function change(label,fn,redraw=true){return enqueue(async()=>{const next=clone(env);fn(next.data);C.validate(next.data);next.data.audit.unshift({at:new Date().toISOString(),label});next.data.audit=next.data.audit.slice(0,500);next.meta.generation++;next.meta.dirty=true;next.meta.savedAt=new Date().toISOString();await writeDB(next);env=next;if(redraw)render();else updateStatus();scheduleSync();}).catch(e=>{toast('บันทึกไม่สำเร็จ: '+e.message);throw e;});}
function updateStatus(){const b=$('syncStatus');b.className='sync-status'+(env.meta.dirty?' dirty':'');b.textContent=busy?'กำลังซิงก์…':!navigator.onLine?'ออฟไลน์':cloudConflict?'ข้อมูลขัดกัน':syncError?'ซิงก์ไม่สำเร็จ':!cloud.url?'บันทึกในเครื่อง':env.meta.dirty?'รอสำรอง':'สำรองแล้ว';if(cloudConflict||syncError)b.classList.add('error');b.title=syncError;$('saveStatus').textContent=env.meta.savedAt?'บันทึก '+new Date(env.meta.savedAt).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'}):'';}
const data=()=>env.data, room=()=>data().rooms.find(r=>r.id===ui.room), rooms=()=>data().rooms.filter(r=>r.termId===ui.term&&!r.archived), roster=()=>C.activeStudents(data(),ui.room), tasks=()=>C.tasks(data(),ui.room,ui.subject), cfg=()=>C.settings(data(),ui.room,ui.subject);
