function requireCourse(){if(!rooms().length)return empty('เริ่มจากนำเข้ารายชื่อนักเรียน','ใช้ไฟล์เลขที่ / ชื่อ–นามสกุล / ชั้น ระบบจะแยกห้องให้เอง',button('นำเข้ารายชื่อนักเรียน','students-file','','primary'));if(!subjectList().length)return empty('สร้างวิชาและเลือกห้องที่เรียน','รายชื่อแต่ละห้องพร้อมแล้ว เพิ่มวิชาก่อนเริ่มใช้งาน',button('＋ สร้างวิชา','subject-add','','primary'));if(!courseRooms().length)return empty('เลือกห้องที่เรียนวิชานี้','เพิ่มห้องที่เรียนในวิชา '+esc(ui.subject),button('เลือกห้องที่เรียน','subject-edit',`data-id="${esc(subjectList().find(s=>s.name===ui.subject)?.id)}"`,'primary'));return null;}
function session(){return data().sessions.find(s=>s.roomId===ui.room&&s.subject===ui.subject&&s.date===ui.date&&s.period===Number(ui.period));}
function draft(d){let s=d.sessions.find(s=>s.roomId===ui.room&&s.subject===ui.subject&&s.date===ui.date&&s.period===Number(ui.period));if(!s){const ids=C.activeStudents(d,ui.room).map(s=>s.id);if(!ids.length)throw Error('เพิ่มนักเรียนก่อนเช็กชื่อ');s={id:C.id(),roomId:ui.room,subject:ui.subject,date:ui.date,period:Number(ui.period),roster:ids,statuses:{},note:'',complete:false};d.sessions.push(s);}return s;}
