function context(){if(ui.page==='reports'&&rooms().length)return `<h1 class="coach-report-heading">สรุปผลรายห้อง</h1><div class="report-filters"><select id="reportRoom" aria-label="ห้องเรียนรายงาน">${courseRooms().map(r=>option(r.id,r.name,ui.room)).join('')}</select><select id="subjectSelect" aria-label="วิชา">${subjectNames().map(sub=>option(sub,sub,ui.subject)).join('')}</select></div>`;if(!rooms().length)return '';if(['attendance','scores'].includes(ui.page))return '';if(ui.page==='students')return `<div class="rooms-strip">${rooms().map(r=>button(esc(r.name),'select-room',`data-id="${esc(r.id)}"`,r.id===ui.room?'primary':'')).join('')}</div>`;return `<div class="course-strip"><div class="subject-banner"><span class="sport">${icon('physical')}</span><div><select aria-label="วิชา" id="subjectSelect">${subjectNames().map(s=>option(s,s,ui.subject)).join('')}</select><small>เลือกวิชาและห้องที่เรียน</small></div></div><div class="rooms-strip">${(COURSE_PAGES.includes(ui.page)?courseRooms():rooms()).map(r=>`<button class="room-chip ${r.id===ui.room?'active':''}" data-action="select-room" data-id="${esc(r.id)}"><strong>${esc(r.name)}</strong><small>${C.activeStudents(data(),r.id).length} คน</small></button>`).join('')}<button class="room-add" data-action="${COURSE_PAGES.includes(ui.page)?'subject-edit':'students-file'}" data-id="${esc(subjectList().find(s=>s.name===ui.subject)?.id)}" aria-label="${COURSE_PAGES.includes(ui.page)?'เลือกห้องที่เรียน':'นำเข้ารายชื่อ'}">＋</button></div></div>`;}
