function attendanceBoard(home=false){if(!home)return attendanceCards();const students=selectedStudents(),s=session(),count=s?Object.keys(s.statuses).length:0,complete=!!s&&C.complete(s),ts=tasks().slice(0,3);return `<section class="board"><div class="board-head"><div class="room-title">${icon('students')}<div><h2>${esc(room().name)}</h2><small>${esc(ui.subject)} · ${students.length} คน ${s?.complete?'· เช็กครบแล้ว':s?'· ฉบับร่าง':''}</small></div></div><div class="actions">${dateControls()}</div></div>${students.length?`<div class="table-scroll" tabindex="0"><table class="${home?'dashboard':'attendance'}-table"><thead><tr><th class="hide-mobile">#</th><th>รหัส · ชื่อ–นามสกุล</th><th>เช็กชื่อ</th>${home?ts.map(t=>`<th class="hide-mobile">${esc(t.name)}<br><small>เต็ม ${fmt(t.max)}</small></th>`).join('')+'<th class="hide-mobile">รวม / 100</th>':''}</tr></thead><tbody>${students.map((st,i)=>`<tr><td class="hide-mobile">${i+1}</td><td>${person(st)}</td><td>${attendanceSelect(st)}</td>${home?ts.map(t=>`<td class="hide-mobile">${scoreInput(st,t)}</td>`).join('')+`<td class="hide-mobile"><span class="total">${fmt(C.result(data(),st,ui.subject).total)}</span></td>`:''}</tr>`).join('')}</tbody></table></div>`:empty('ยังไม่มีนักเรียน','เพิ่มรายชื่อก่อนเริ่มเช็กชื่อ',button('＋ เพิ่มนักเรียน','student-add','','primary'))}<div class="board-foot"><span>${count}/${students.length} คน · มา/ลา/สาย = 1 · ขาด/หนี = 0<br>${s?.complete?'คาบนี้นำไปคิดเวลาเรียนแล้ว':'ฉบับร่างไม่นับเวลาเรียน จนกว่าจะเช็กครบและกดบันทึกคาบ'}</span>${button(s?.complete?'✓ เช็กชื่อครบแล้ว':'✓ บันทึกการเช็กชื่อ','session-complete',!complete?'disabled':'','green')}</div></section>`;}
